test('Place links atomic producer: monotonic timing bands and unavailable clock',()=>{
 // Each explicit numeric row independently pins half-open elapsed and remaining bands.
 for(const [delta,budget,elapsed,remaining]of [[0,120000,'under-one','sixty-plus'],[999,120000,'under-one','sixty-plus'],[1000,120000,'one-to-ten','sixty-plus'],[9999,120000,'one-to-ten','sixty-plus'],[10000,120000,'ten-to-thirty','sixty-plus'],[29999,120000,'ten-to-thirty','sixty-plus'],[30000,120000,'thirty-to-sixty','sixty-plus'],[59999,120000,'thirty-to-sixty','sixty-plus'],[60000,120000,'sixty-to-ninety','sixty-plus'],[89999,120000,'sixty-to-ninety','thirty-to-sixty'],[90000,120000,'ninety-to-one-twenty','thirty-to-sixty'],[119999,120000,'ninety-to-one-twenty','under-one'],[120000,120000,'one-twenty-plus','zero'],[130000,120000,'one-twenty-plus','zero'],[0,1,'under-one','under-one'],[0,999,'under-one','under-one'],[0,1000,'under-one','one-to-ten'],[0,9999,'under-one','one-to-ten'],[0,10000,'under-one','ten-to-thirty'],[0,29999,'under-one','ten-to-thirty'],[0,30000,'under-one','thirty-to-sixty'],[0,59999,'under-one','thirty-to-sixty'],[0,60000,'under-one','sixty-plus']]){const x=harness(),i=info({timeout:budget});x.h.beginPlaceLinksAtomicDiagnostic(i);x.clock.value=1000+delta;caught(x,i);const calls=x.clock.calls;finish(x,i);assert.equal(x.clock.calls,calls,'finalize/capture cannot sample clock');assert.deepEqual(emitted(i),[marker(card({elapsed,remaining}))]);for(const map of x.maps){const state=map.get(i);if(state){const numeric=[];const collect=value=>{if(typeof value==='number')numeric.push(value);else if(value&&typeof value==='object')for(const v of Object.values(value))collect(v);};collect(state);assert.ok(numeric.every(v=>v===1),'release private numeric clock/budget at finalize');}}}
 for(const bad of [NaN,Infinity,-Infinity,-1]){const x=harness(),i=info();x.h.beginPlaceLinksAtomicDiagnostic(i);x.clock.value=bad;caught(x,i);x.clock.value=1001;x.h.setPlaceLinksAtomicBoundary(i,'products','fresh','linked-count');finish(x,i);assert.deepEqual(emitted(i),[marker(card({elapsed:'unavailable',remaining:'unavailable'}))]);}
 for(const timeout of [0,-1,NaN,Infinity,undefined,'120000']){const x=harness(),i=info({timeout});x.h.beginPlaceLinksAtomicDiagnostic(i);caught(x,i);finish(x,i);assert.deepEqual(emitted(i),[marker(card({elapsed:'unavailable',remaining:'unavailable'}))]);}
 const x=harness(),i=info();let reads=0;Object.defineProperty(i,'timeout',{get(){reads++;if(reads>1)throw Error('later budget read');return 120000;}});x.h.beginPlaceLinksAtomicDiagnostic(i);x.clock.value=1002;caught(x,i);finish(x,i);assert.equal(reads,1);assert.deepEqual(emitted(i),[marker(card())]);
 const backwards=harness(),b=info();backwards.h.beginPlaceLinksAtomicDiagnostic(b);backwards.clock.value=2000;backwards.h.setPlaceLinksAtomicBoundary(b,'products','fresh','iteration-entry');backwards.clock.value=1999;backwards.h.setPlaceLinksAtomicBoundary(b,'products','fresh','fresh-response');backwards.h.recordPlaceLinksAtomicBody(b,'caught');backwards.h.setPlaceLinksAtomicCleanup(b,'completed');backwards.clock.value=3000;finish(backwards,b);assert.deepEqual(emitted(b),[marker(card({elapsed:'unavailable',remaining:'unavailable'}))]);
});

