 for(const status of ['failed','timedOut','interrupted']){const x=harness(),i=info({status}),original=i.errors[0];x.h.beginPlaceLinksAtomicDiagnostic(i);caught(x,i);finish(x,i);finish(x,i);assert.deepEqual(emitted(i),[marker(card())]);assert.equal(i.errors[0],original);assert.deepEqual(original,{message:'native error'});assert.doesNotMatch(emitted(i)[0],/private|secret|https|authorization|cookie|session|120000/);}
