 for(const poison of [i=>Object.defineProperty(i,'errors',{get(){throw Error('private');}}),i=>Object.freeze(i.errors),i=>Object.defineProperty(i.errors,'push',{get(){throw Error('private');}}),i=>i.errors.push=()=>{throw Error('private');},i=>Object.defineProperty(i,'status',{get(){throw Error('private');}})]){const x=harness(),i=info(),errors=i.errors,original=errors[0];x.h.beginPlaceLinksAtomicDiagnostic(i);caught(x,i);x.h.finalizePlaceLinksAtomicDiagnostic(i);poison(i);sync(()=>x.h.capturePlaceLinksAtomicDiagnostic(i));assert.equal(errors.length,1);assert.equal(errors[0],original);}
 for(const existing of [null,marker(card()),'embedded '+prefix+'malformed]']){const x=harness(),i=info(),errors=i.errors,original=i.errors[0];let reads=0;const retained=existing===null?Object.defineProperty({},'message',{enumerable:true,get(){reads++;throw Error('private native message');}}):{message:existing};errors.push(retained);const descriptor=Object.getOwnPropertyDescriptor(retained,'message');x.h.beginPlaceLinksAtomicDiagnostic(i);caught(x,i);finish(x,i);finish(x,i);assert.equal(reads,0,'producer never reads existing native error messages');assert.equal(i.errors,errors);assert.equal(errors[0],original);assert.equal(errors[1],retained);assert.deepEqual(Object.getOwnPropertyDescriptor(retained,'message'),descriptor);assert.equal(errors.length,3,'WeakSet owns one append without native-message prefix inspection');assert.equal(errors[2].message,marker(card()));}
 const arrayPrivate=harness(),api=info(),privateErrors=api.errors;let entryReads=0;const nativeSlot=Object.defineProperty(privateErrors,'0',{configurable:true,enumerable:true,get(){entryReads++;throw Error('private native array entry');}}),slotDescriptor=Object.getOwnPropertyDescriptor(nativeSlot,'0');arrayPrivate.h.beginPlaceLinksAtomicDiagnostic(api);caught(arrayPrivate,api);finish(arrayPrivate,api);finish(arrayPrivate,api);assert.equal(entryReads,0,'producer never scans native error array entries');assert.equal(api.errors,privateErrors);assert.deepEqual(Object.getOwnPropertyDescriptor(privateErrors,'0'),slotDescriptor);assert.equal(privateErrors.length,2);assert.equal(privateErrors[1].message,marker(card()));
 for(const [name,args]of [[names[1],['products','fresh','fresh-response']],[names[2],['caught']]]){const x=harness(),i=info();x.h.beginPlaceLinksAtomicDiagnostic(i);caught(x,i);x.clock.fail=true;sync(()=>x.h[name](i,...args));x.clock.fail=false;finish(x,i);assert.deepEqual(emitted(i),[],'fallible clock transition dependency omission '+name);}
 const duplicate=harness(),d=info();duplicate.h.beginPlaceLinksAtomicDiagnostic(d);caught(duplicate,d);duplicate.clock.fail=true;sync(()=>duplicate.h.beginPlaceLinksAtomicDiagnostic(d));duplicate.clock.fail=false;finish(duplicate,d);assert.deepEqual(emitted(d),[marker(card())],'begin does not replace an existing entry');
 const badBudget=harness(),bb=info();Object.defineProperty(bb,'timeout',{get(){throw Error('private budget');}});sync(()=>badBudget.h.beginPlaceLinksAtomicDiagnostic(bb));caught(badBudget,bb);finish(badBudget,bb);assert.deepEqual(emitted(bb),[]);
 const noClock=harness(),nc=info();noClock.h.beginPlaceLinksAtomicDiagnostic(nc);caught(noClock,nc);noClock.clock.fail=true;const noClockCalls=noClock.clock.calls;for(const cleanup of ['release','listener-off','unroute','completed'])sync(()=>noClock.h.setPlaceLinksAtomicCleanup(nc,cleanup));finish(noClock,nc);assert.equal(noClock.clock.calls,noClockCalls,'successful cleanup/finalize/capture are clock independent');assert.deepEqual(emitted(nc),[marker(card())]);
